# Completa la línea marcada y compruébala con py check.
import math

def probabilidad(x, pesos, sesgo):
    z = sesgo
    for xi, wi in zip(x, pesos):
        z = z   # ← cambia esta línea: suma cada entrada por su peso
    return 1 / (1 + math.exp(-z))

print(probabilidad([1.0, 2.0], [0.5, -0.25], 0.1))   # unos 0.525
